eventView(){
 const e=this.s.eventQueue[0];if(!e)return null;
 const d=EVENTS[e.id],c=this.country(e.context.country);let title=d.title,body=d.body;
 if(e.context.echo&&d.echo){title=d.echo.title;body=d.echo.body;}
 const choices=d.choices.map(ch=>{const cost=ch.cost||{},blocked=[...this.shortages(cost)];
  if(ch.requires==='recovery'&&!this.s.craft.some(a=>a.type==='recovery'||a.type==='platform'))blocked.push('No recovery-capable craft');
  if(ch.requires==='contact'&&(c?.contact||0)<2)blocked.push('Requires a backchannel');return {...ch,blocked};});
 // A mandatory paused event must never require currency the player cannot obtain while paused.
 // Declining intervention is costly in world-state consequences, but never resource-gated.
 if(!choices.some(ch=>!ch.blocked.length))choices.push({id:'stand_down',label:'Accept the consequences',text:'The Network cannot fund an intervention. Let this incident run its course; public scrutiny and local suspicion rise.',cost:{},effects:{belief:5,evidence:3,coherence:4,suspicion:6,pattern:3},blocked:[]});
 return {...d,...e,title,body:body.replaceAll('{country}',c?.name||'the region'),choices};
}
